normative_text.utility.intcmp:
22.2.7 Integer comparison functions [utility.intcmp]
🔗
template<class T, class U>
  constexpr bool cmp_equal(T t, U u) noexcept;
1
#
Mandates: Each of T and U is
a signed or unsigned integer type ([basic.fundamental]).
2
#
Effects: Equivalent to:
using UT = make_unsigned_t<T>;
using UU = make_unsigned_t<U>;
if constexpr (is_signed_v<T> == is_signed_v<U>)
  return t == u;
else if constexpr (is_signed_v<T>)
  return t < 0 ? false : UT(t) == u;
else
  return u < 0 ? false : t == UU(u);
🔗
template<class T, class U>
  constexpr bool cmp_not_equal(T t, U u) noexcept;
3
#
Effects: Equivalent to: return !cmp_equal(t, u);
🔗
template<class T, class U>
  constexpr bool cmp_less(T t, U u) noexcept;
4
#
Mandates: Each of T and U is
a signed or unsigned integer type ([basic.fundamental]).
5
#
Effects: Equivalent to:
using UT = make_unsigned_t<T>;
using UU = make_unsigned_t<U>;
if constexpr (is_signed_v<T> == is_signed_v<U>)
  return t < u;
else if constexpr (is_signed_v<T>)
  return t < 0 ? true : UT(t) < u;
else
  return u < 0 ? false : t < UU(u);
🔗
template<class T, class U>
  constexpr bool cmp_greater(T t, U u) noexcept;
6
#
Effects: Equivalent to: return cmp_less(u, t);
🔗
template<class T, class U>
  constexpr bool cmp_less_equal(T t, U u) noexcept;
7
#
Effects: Equivalent to: return !cmp_greater(t, u);
🔗
template<class T, class U>
  constexpr bool cmp_greater_equal(T t, U u) noexcept;
8
#
Effects: Equivalent to: return !cmp_less(t, u);
🔗
template<class R, class T>
  constexpr bool in_range(T t) noexcept;
9
#
Mandates: Each of T and R is
a signed or unsigned integer type ([basic.fundamental]).
10
#
Effects: Equivalent to:
return cmp_greater_equal(t, numeric_limits<R>::min()) &&
       cmp_less_equal(t, numeric_limits<R>::max());
11
#
[Note 1: These function templates cannot be used to compare
byte,
char,
char8_t,
char16_t,
char32_t,
wchar_t, and
bool.
 — end note]

